// GERADO AUTOMATICAMENTE por scripts/gen-migrations.mjs — não edite à mão.
// Edite os arquivos em supabase/ e rode `npm run build`.

export const MIGRATIONS: { nome: string; sql: string }[] = [
  { nome: "001_schema.sql", sql: "-- =====================================================================\n-- dindi — schema principal\n-- Rode este arquivo no SQL Editor do Supabase (uma vez só).\n-- =====================================================================\n\ncreate extension if not exists \"pgcrypto\";\n\n-- ---------------------------------------------------------------------\n-- Casa (household) = o espaço compartilhado de um casal / família.\n-- Todo dado do sistema pertence a uma casa.\n-- ---------------------------------------------------------------------\ncreate table if not exists households (\n  id          uuid primary key default gen_random_uuid(),\n  name        text not null,\n  created_at  timestamptz not null default now()\n);\n\ncreate table if not exists household_members (\n  household_id uuid not null references households(id) on delete cascade,\n  user_id      uuid not null references auth.users(id) on delete cascade,\n  display_name text not null,\n  role         text not null default 'member' check (role in ('owner','member')),\n  created_at   timestamptz not null default now(),\n  primary key (household_id, user_id)\n);\n\ncreate index if not exists idx_members_user on household_members(user_id);\n\ncreate table if not exists household_invites (\n  id           uuid primary key default gen_random_uuid(),\n  household_id uuid not null references households(id) on delete cascade,\n  code         text not null unique,\n  email        text,\n  created_by   uuid not null references auth.users(id) on delete cascade,\n  accepted_by  uuid references auth.users(id) on delete set null,\n  accepted_at  timestamptz,\n  expires_at   timestamptz not null default (now() + interval '30 days'),\n  created_at   timestamptz not null default now()\n);\n\n-- ---------------------------------------------------------------------\n-- Contas: conta corrente, poupança e cartão de crédito\n-- ---------------------------------------------------------------------\ncreate table if not exists accounts (\n  id             uuid primary key default gen_random_uuid(),\n  household_id   uuid not null references households(id) on delete cascade,\n  name           text not null,\n  type           text not null check (type in ('checking','savings','credit_card')),\n  owner_user_id  uuid references auth.users(id) on delete set null, -- null = conjunta\n  closing_day    int check (closing_day between 1 and 31),\n  due_day        int check (due_day between 1 and 31),\n  opening_balance numeric(14,2) not null default 0,\n  archived       boolean not null default false,\n  created_at     timestamptz not null default now(),\n  constraint card_needs_days check (\n    type <> 'credit_card' or (closing_day is not null and due_day is not null)\n  )\n);\n\ncreate index if not exists idx_accounts_household on accounts(household_id);\n\n-- ---------------------------------------------------------------------\n-- Categorias\n-- ---------------------------------------------------------------------\ncreate table if not exists categories (\n  id           uuid primary key default gen_random_uuid(),\n  household_id uuid not null references households(id) on delete cascade,\n  name         text not null,\n  kind         text not null default 'expense' check (kind in ('expense','income','both')),\n  -- Em que \"balde\" o gasto cai — ver 004_grupos.sql.\n  bucket       text not null default 'dia_a_dia'\n               check (bucket in ('fixo','dia_a_dia','lazer','guardar','receita')),\n  emoji        text,\n  archived     boolean not null default false,\n  created_at   timestamptz not null default now(),\n  unique (household_id, name)\n);\n\ncreate index if not exists idx_categories_household on categories(household_id);\n\n-- ---------------------------------------------------------------------\n-- Regras recorrentes (aluguel, salário, assinaturas...)\n-- ---------------------------------------------------------------------\ncreate table if not exists recurring_rules (\n  id                   uuid primary key default gen_random_uuid(),\n  household_id         uuid not null references households(id) on delete cascade,\n  description          text not null,\n  amount               numeric(14,2) not null check (amount > 0),\n  type                 text not null default 'expense' check (type in ('expense','income')),\n  category_id          uuid references categories(id) on delete set null,\n  account_id           uuid not null references accounts(id) on delete cascade,\n  paid_by_user_id      uuid references auth.users(id) on delete set null,\n  day_of_month         int not null check (day_of_month between 1 and 31),\n  start_date           date not null default current_date,\n  end_date             date,\n  active               boolean not null default true,\n  last_generated_month date, -- primeiro dia do último mês já gerado (evita duplicar)\n  created_at           timestamptz not null default now()\n);\n\ncreate index if not exists idx_recurring_household on recurring_rules(household_id);\n\n-- ---------------------------------------------------------------------\n-- Compras parceladas no cartão\n-- ---------------------------------------------------------------------\ncreate table if not exists credit_card_purchases (\n  id                  uuid primary key default gen_random_uuid(),\n  household_id        uuid not null references households(id) on delete cascade,\n  account_id          uuid not null references accounts(id) on delete cascade,\n  description         text not null,\n  total_amount        numeric(14,2) not null check (total_amount > 0),\n  installments_count  int not null check (installments_count between 1 and 72),\n  first_invoice_month date not null, -- sempre dia 1 do mês\n  purchase_date       date not null default current_date,\n  category_id         uuid references categories(id) on delete set null,\n  paid_by_user_id     uuid references auth.users(id) on delete set null,\n  created_at          timestamptz not null default now()\n);\n\ncreate index if not exists idx_purchases_household on credit_card_purchases(household_id);\n\n-- ---------------------------------------------------------------------\n-- Faturas do cartão\n-- ---------------------------------------------------------------------\ncreate table if not exists invoices (\n  id                   uuid primary key default gen_random_uuid(),\n  household_id         uuid not null references households(id) on delete cascade,\n  account_id           uuid not null references accounts(id) on delete cascade,\n  reference_month      date not null, -- dia 1 do mês de referência\n  closing_date         date not null,\n  due_date             date not null,\n  total_amount         numeric(14,2) not null default 0,\n  status               text not null default 'open' check (status in ('open','closed','paid')),\n  paid_at              timestamptz,\n  paid_from_account_id uuid references accounts(id) on delete set null,\n  created_at           timestamptz not null default now(),\n  unique (account_id, reference_month)\n);\n\ncreate index if not exists idx_invoices_household on invoices(household_id);\n\n-- ---------------------------------------------------------------------\n-- Transações (gastos e receitas)\n-- ---------------------------------------------------------------------\ncreate table if not exists transactions (\n  id                 uuid primary key default gen_random_uuid(),\n  household_id       uuid not null references households(id) on delete cascade,\n  date               date not null default current_date,\n  amount             numeric(14,2) not null check (amount > 0),\n  description        text not null,\n  type               text not null check (type in ('expense','income')),\n  category_id        uuid references categories(id) on delete set null,\n  account_id         uuid not null references accounts(id) on delete cascade,\n  paid_by_user_id    uuid references auth.users(id) on delete set null,\n  recurring_rule_id  uuid references recurring_rules(id) on delete set null,\n  purchase_id        uuid references credit_card_purchases(id) on delete cascade,\n  installment_number int,\n  -- só para transações de cartão: em qual fatura (dia 1 do mês) ela cai\n  invoice_month      date,\n  note               text,\n  created_at         timestamptz not null default now()\n);\n\ncreate index if not exists idx_tx_household_date on transactions(household_id, date desc);\ncreate index if not exists idx_tx_account on transactions(account_id);\ncreate index if not exists idx_tx_category on transactions(category_id);\ncreate index if not exists idx_tx_invoice on transactions(account_id, invoice_month);\ncreate index if not exists idx_tx_purchase on transactions(purchase_id);\n\n-- ---------------------------------------------------------------------\n-- Orçamento por categoria/mês\n-- ---------------------------------------------------------------------\ncreate table if not exists budgets (\n  id              uuid primary key default gen_random_uuid(),\n  household_id    uuid not null references households(id) on delete cascade,\n  category_id     uuid not null references categories(id) on delete cascade,\n  reference_month date not null, -- dia 1 do mês\n  limit_amount    numeric(14,2) not null check (limit_amount > 0),\n  created_at      timestamptz not null default now(),\n  unique (household_id, category_id, reference_month)\n);\n\n-- ---------------------------------------------------------------------\n-- Metas de economia\n-- ---------------------------------------------------------------------\ncreate table if not exists goals (\n  id             uuid primary key default gen_random_uuid(),\n  household_id   uuid not null references households(id) on delete cascade,\n  name           text not null,\n  -- 'emergencia' = o colchão; 'sonho' = tudo que a casa quer conquistar.\n  kind           text not null default 'sonho' check (kind in ('emergencia','sonho')),\n  target_amount  numeric(14,2) not null check (target_amount > 0),\n  target_date    date,\n  current_amount numeric(14,2) not null default 0,\n  archived       boolean not null default false,\n  created_at     timestamptz not null default now()\n);\n\ncreate index if not exists idx_goals_household on goals(household_id);\n\ncreate table if not exists goal_contributions (\n  id           uuid primary key default gen_random_uuid(),\n  household_id uuid not null references households(id) on delete cascade,\n  goal_id      uuid not null references goals(id) on delete cascade,\n  date         date not null default current_date,\n  amount       numeric(14,2) not null,\n  user_id      uuid references auth.users(id) on delete set null,\n  note         text,\n  created_at   timestamptz not null default now()\n);\n\n-- Mantém goals.current_amount sempre em dia\ncreate or replace function sync_goal_amount() returns trigger\nlanguage plpgsql security definer set search_path = public as $$\ndeclare gid uuid;\nbegin\n  gid := coalesce(new.goal_id, old.goal_id);\n  update goals\n     set current_amount = coalesce((select sum(amount) from goal_contributions where goal_id = gid), 0)\n   where id = gid;\n  return null;\nend $$;\n\ndrop trigger if exists trg_sync_goal_amount on goal_contributions;\ncreate trigger trg_sync_goal_amount\nafter insert or update or delete on goal_contributions\nfor each row execute function sync_goal_amount();\n\n-- =====================================================================\n-- OAuth — usado pelo Claude para conectar no MCP\n-- =====================================================================\ncreate table if not exists oauth_clients (\n  client_id                  text primary key,\n  client_secret              text,\n  client_name                text,\n  redirect_uris              jsonb not null default '[]'::jsonb,\n  grant_types                jsonb not null default '[\"authorization_code\",\"refresh_token\"]'::jsonb,\n  token_endpoint_auth_method text not null default 'none',\n  created_at                 timestamptz not null default now()\n);\n\ncreate table if not exists oauth_authorization_codes (\n  code                  text primary key,\n  client_id             text not null references oauth_clients(client_id) on delete cascade,\n  user_id               uuid not null references auth.users(id) on delete cascade,\n  household_id          uuid not null references households(id) on delete cascade,\n  redirect_uri          text not null,\n  code_challenge        text,\n  code_challenge_method text,\n  scope                 text,\n  resource              text,\n  expires_at            timestamptz not null,\n  used                  boolean not null default false,\n  created_at            timestamptz not null default now()\n);\n\ncreate table if not exists oauth_tokens (\n  id            uuid primary key default gen_random_uuid(),\n  token_hash    text not null unique,\n  token_type    text not null check (token_type in ('access','refresh')),\n  client_id     text not null references oauth_clients(client_id) on delete cascade,\n  user_id       uuid not null references auth.users(id) on delete cascade,\n  household_id  uuid not null references households(id) on delete cascade,\n  scope         text,\n  expires_at    timestamptz,\n  revoked       boolean not null default false,\n  last_used_at  timestamptz,\n  created_at    timestamptz not null default now()\n);\n\ncreate index if not exists idx_oauth_tokens_user on oauth_tokens(user_id);\n" },
  { nome: "002_rls.sql", sql: "-- =====================================================================\n-- dindi — Row Level Security\n-- Garante que cada casa só enxerga os próprios dados.\n-- Rode DEPOIS do 001_schema.sql.\n-- =====================================================================\n\n-- Função auxiliar: o usuário logado é membro desta casa?\n-- SECURITY DEFINER evita recursão infinita nas policies de household_members.\ncreate or replace function public.is_household_member(hid uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select exists (\n    select 1 from household_members\n     where household_id = hid and user_id = auth.uid()\n  );\n$$;\n\ncreate or replace function public.my_household_ids()\nreturns setof uuid\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select household_id from household_members where user_id = auth.uid();\n$$;\n\n-- ---------------------------------------------------------------------\nalter table households            enable row level security;\nalter table household_members     enable row level security;\nalter table household_invites     enable row level security;\nalter table accounts              enable row level security;\nalter table categories            enable row level security;\nalter table recurring_rules       enable row level security;\nalter table credit_card_purchases enable row level security;\nalter table invoices              enable row level security;\nalter table transactions          enable row level security;\nalter table budgets               enable row level security;\nalter table goals                 enable row level security;\nalter table goal_contributions    enable row level security;\nalter table oauth_clients         enable row level security;\nalter table oauth_authorization_codes enable row level security;\nalter table oauth_tokens          enable row level security;\n\n-- households -----------------------------------------------------------\ndrop policy if exists households_select on households;\ncreate policy households_select on households\n  for select using (public.is_household_member(id));\n\ndrop policy if exists households_update on households;\ncreate policy households_update on households\n  for update using (public.is_household_member(id));\n\n-- household_members ----------------------------------------------------\ndrop policy if exists members_select on household_members;\ncreate policy members_select on household_members\n  for select using (public.is_household_member(household_id));\n\ndrop policy if exists members_update_self on household_members;\ncreate policy members_update_self on household_members\n  for update using (user_id = auth.uid());\n\n-- household_invites ----------------------------------------------------\ndrop policy if exists invites_select on household_invites;\ncreate policy invites_select on household_invites\n  for select using (public.is_household_member(household_id));\n\n-- ---------------------------------------------------------------------\n-- Tabelas de dados: mesma regra para tudo (membro da casa = acesso total)\n-- ---------------------------------------------------------------------\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array[\n    'accounts','categories','recurring_rules','credit_card_purchases',\n    'invoices','transactions','budgets','goals','goal_contributions'\n  ] loop\n    execute format('drop policy if exists %I_all on %I', t, t);\n    execute format(\n      'create policy %I_all on %I for all\n         using (public.is_household_member(household_id))\n         with check (public.is_household_member(household_id))', t, t);\n  end loop;\nend $$;\n\n-- ---------------------------------------------------------------------\n-- OAuth: nenhuma policy permissiva.\n-- Só o servidor (service_role, que ignora RLS) acessa essas tabelas.\n-- O usuário pode ver e revogar as próprias conexões.\n-- ---------------------------------------------------------------------\ndrop policy if exists tokens_select_own on oauth_tokens;\ncreate policy tokens_select_own on oauth_tokens\n  for select using (user_id = auth.uid());\n\ndrop policy if exists tokens_revoke_own on oauth_tokens;\ncreate policy tokens_revoke_own on oauth_tokens\n  for update using (user_id = auth.uid());\n" },
  { nome: "003_functions.sql", sql: "-- =====================================================================\n-- dindi — funções de onboarding\n-- Rode DEPOIS do 002_rls.sql.\n-- =====================================================================\n\n-- Categorias que toda casa nova ganha de brinde\ncreate or replace function public.seed_default_categories(hid uuid)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  insert into categories (household_id, name, kind, bucket, emoji) values\n    -- chega todo mês, não dá para escolher\n    (hid, 'Moradia',        'expense', 'fixo',      '🏠'),\n    (hid, 'Contas de casa', 'expense', 'fixo',      '💡'),\n    (hid, 'Assinaturas',    'expense', 'fixo',      '📺'),\n    (hid, 'Educação',       'expense', 'fixo',      '📚'),\n    -- o básico de viver\n    (hid, 'Mercado',        'expense', 'dia_a_dia', '🛒'),\n    (hid, 'Transporte',     'expense', 'dia_a_dia', '🚗'),\n    (hid, 'Saúde',          'expense', 'dia_a_dia', '💊'),\n    (hid, 'Pets',           'expense', 'dia_a_dia', '🐶'),\n    (hid, 'Outros',         'expense', 'dia_a_dia', '📦'),\n    -- o que é escolha\n    (hid, 'Restaurante',    'expense', 'lazer',     '🍽️'),\n    (hid, 'Lazer',          'expense', 'lazer',     '🎬'),\n    (hid, 'Compras',        'expense', 'lazer',     '🛍️'),\n    (hid, 'Presentes',      'expense', 'lazer',     '🎁'),\n    (hid, 'Viagem',         'expense', 'lazer',     '✈️'),\n    -- o que sai da conta para virar reserva\n    (hid, 'Reserva',        'expense', 'guardar',   '🐷'),\n    (hid, 'Investimentos',  'expense', 'guardar',   '🌱'),\n    -- o que entra\n    (hid, 'Salário',        'income',  'receita',   '💼'),\n    (hid, 'Freela',         'income',  'receita',   '💻'),\n    (hid, 'Rendimentos',    'income',  'receita',   '📈'),\n    (hid, 'Outras receitas','income',  'receita',   '➕')\n  on conflict (household_id, name) do nothing;\nend $$;\n\n-- Cria a casa do usuário logado e o coloca como dono.\ncreate or replace function public.bootstrap_household(\n  p_household_name text,\n  p_display_name   text\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  hid uuid;\n  uid uuid := auth.uid();\nbegin\n  if uid is null then\n    raise exception 'não autenticado';\n  end if;\n\n  -- se já tem casa, devolve a existente (idempotente)\n  select household_id into hid from household_members where user_id = uid limit 1;\n  if hid is not null then\n    return hid;\n  end if;\n\n  insert into households (name) values (coalesce(nullif(trim(p_household_name), ''), 'Nossa casa'))\n  returning id into hid;\n\n  insert into household_members (household_id, user_id, display_name, role)\n  values (hid, uid, coalesce(nullif(trim(p_display_name), ''), 'Eu'), 'owner');\n\n  perform seed_default_categories(hid);\n\n  return hid;\nend $$;\n\n-- Gera um convite para o parceiro entrar na casa.\ncreate or replace function public.create_invite(p_email text default null)\nreturns text\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  hid  uuid;\n  uid  uuid := auth.uid();\n  code text;\nbegin\n  select household_id into hid from household_members where user_id = uid limit 1;\n  if hid is null then raise exception 'você ainda não tem uma casa'; end if;\n\n  code := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));\n\n  insert into household_invites (household_id, code, email, created_by)\n  values (hid, code, p_email, uid);\n\n  return code;\nend $$;\n\n-- Entra numa casa usando o código de convite.\ncreate or replace function public.accept_invite(\n  p_code         text,\n  p_display_name text\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  inv  household_invites%rowtype;\n  uid  uuid := auth.uid();\nbegin\n  if uid is null then raise exception 'não autenticado'; end if;\n\n  select * into inv from household_invites\n   where code = upper(trim(p_code)) and accepted_at is null and expires_at > now();\n\n  if inv.id is null then raise exception 'convite inválido ou expirado'; end if;\n\n  if exists (select 1 from household_members where user_id = uid) then\n    raise exception 'você já faz parte de uma casa';\n  end if;\n\n  insert into household_members (household_id, user_id, display_name, role)\n  values (inv.household_id, uid, coalesce(nullif(trim(p_display_name), ''), 'Eu'), 'member');\n\n  update household_invites\n     set accepted_at = now(), accepted_by = uid\n   where id = inv.id;\n\n  return inv.household_id;\nend $$;\n" },
  { nome: "004_grupos.sql", sql: "-- =====================================================================\n-- dindi — grupos de gasto e tipos de meta\n--\n-- Toda categoria passa a pertencer a um grupo:\n--   fixo      → chega todo mês e não dá para escolher (aluguel, luz, escola)\n--   dia_a_dia → o básico de viver (mercado, transporte, saúde, pet)\n--   lazer     → o que é escolha (restaurante, viagem, compras, presente)\n--   guardar   → o que sai da conta para virar reserva ou meta\n--   receita   → o que entra\n--\n-- E toda meta passa a ser reserva de emergência ou sonho.\n-- =====================================================================\n\n-- ---------------------------------------------------------------------\n-- categories.bucket\n-- ---------------------------------------------------------------------\nalter table categories add column if not exists bucket text not null default 'dia_a_dia';\n\nalter table categories drop constraint if exists categories_bucket_check;\nalter table categories add constraint categories_bucket_check\n  check (bucket in ('fixo','dia_a_dia','lazer','guardar','receita'));\n\n-- Arruma as casas que já existiam, pelo nome das categorias padrão.\nupdate categories set bucket = 'fixo'\n where bucket = 'dia_a_dia'\n   and name in ('Moradia','Contas de casa','Assinaturas','Educação');\n\nupdate categories set bucket = 'lazer'\n where bucket = 'dia_a_dia'\n   and name in ('Restaurante','Lazer','Compras','Presentes','Viagem');\n\nupdate categories set bucket = 'guardar'\n where bucket = 'dia_a_dia'\n   and name in ('Reserva','Poupança','Investimentos');\n\nupdate categories set bucket = 'receita' where kind = 'income';\n\n-- As casas antigas nasceram sem o grupo \"Guardar\" — ele não existia. Dá as duas\n-- categorias para quem ainda não tem, sem mexer em quem já criou as suas.\ninsert into categories (household_id, name, kind, bucket, emoji)\nselect h.id, c.name, 'expense', 'guardar', c.emoji\n  from households h\n cross join (values ('Reserva', '🐷'), ('Investimentos', '🌱')) as c(name, emoji)\n    on conflict (household_id, name) do nothing;\n\ncreate index if not exists idx_categories_bucket on categories(household_id, bucket);\n\n-- ---------------------------------------------------------------------\n-- goals.kind — reserva de emergência é diferente de sonho\n-- ---------------------------------------------------------------------\nalter table goals add column if not exists kind text not null default 'sonho';\n\nalter table goals drop constraint if exists goals_kind_check;\nalter table goals add constraint goals_kind_check check (kind in ('emergencia','sonho'));\n\n-- Uma casa só tem uma reserva de emergência.\ncreate unique index if not exists idx_goals_uma_emergencia\n  on goals(household_id) where kind = 'emergencia' and archived = false;\n\n-- Metas que já existiam e têm cara de reserva viram reserva.\nupdate goals set kind = 'emergencia'\n where kind = 'sonho'\n   and (name ilike '%emerg%' or name ilike '%reserva%')\n   and not exists (\n     select 1 from goals g2\n      where g2.household_id = goals.household_id\n        and g2.kind = 'emergencia'\n        and g2.id <> goals.id\n   );\n" },
  { nome: "005_avisos.sql", sql: "-- =====================================================================\n-- dindi — avisos no celular\n-- Guarda o \"endereço\" de cada aparelho que topou receber o recado da manhã.\n-- =====================================================================\n\ncreate table if not exists push_subscriptions (\n  id           uuid primary key default gen_random_uuid(),\n  household_id uuid not null references households(id) on delete cascade,\n  user_id      uuid not null references auth.users(id) on delete cascade,\n  -- O navegador é quem inventa este endereço; ele é único por aparelho.\n  endpoint     text not null unique,\n  p256dh       text not null,\n  auth         text not null,\n  created_at   timestamptz not null default now(),\n  last_sent_at timestamptz\n);\n\ncreate index if not exists idx_push_household on push_subscriptions(household_id);\n\nalter table push_subscriptions enable row level security;\n\n-- Cada pessoa só enxerga e mexe nos próprios aparelhos. Quem manda o aviso é\n-- a rotina diária, que usa a chave de serviço e não passa por aqui.\ndrop policy if exists push_proprio on push_subscriptions;\ncreate policy push_proprio on push_subscriptions\n  for all\n  using (user_id = auth.uid())\n  with check (user_id = auth.uid());\n" },
  { nome: "006_alertas.sql", sql: "-- ---------------------------------------------------------------------\n-- Memória dos avisos já enviados.\n--\n-- Sem isso, o mesmo recado (\"o lazer passou do ponto\") sairia todo santo\n-- dia enquanto a situação durasse — e em três dias a pessoa desliga as\n-- notificações, levando junto o aviso que importava.\n--\n-- Uma linha por dindi e por tipo de aviso, guardando quando ele saiu pela\n-- última vez. Quem decide o intervalo de cada tipo é o código.\n-- ---------------------------------------------------------------------\ncreate table if not exists public.alert_log (\n  household_id uuid not null references public.households (id) on delete cascade,\n  alert_id     text not null,\n  last_sent    date not null,\n  primary key (household_id, alert_id)\n);\n\nalter table public.alert_log enable row level security;\n\n-- Quem participa do dindi pode ver o histórico dos próprios avisos.\n-- Quem grava é a rotina diária, que roda com a chave de serviço.\ndrop policy if exists alert_log_select on public.alert_log;\ncreate policy alert_log_select on public.alert_log\n  for select using (public.is_household_member(household_id));\n" },
];
